import React from 'react'
import { useState } from 'react';
import axios from 'axios';

function Login() {
    const [email,setEmail] = useState('');
    const [password,setPassword] = useState('');

    const onSubmit = async (e)=>{
        e.preventDefault();
        const loginDetails = {email, password};

        try{
            const response = await axios.post("http://localhost:8080/login", loginDetails);
            if(response.data.id){
                localStorage.setItem('userId',response.data.id)//save user id
                alert("Login successful");
                window.location.reload();
            }else{
            alert('Invalid credentials');
            }
        }catch(err){
            alert('Invalid credentials');
            window.location.href='/userprofile';
        }
    }

  return (
    <div>
      <h1>Login</h1>
      <form onSubmit={(e) => onSubmit(e)}>

        <label htmlFor="email">email</label><br />
        <input type="email" id="email" name="email" value={email} onChange={(e) => setEmail(e.target.value)} required /><br />

        <label htmlFor="password">password</label><br />
        <input type="password" id="password" name="password" value={password} onChange={(e) => setPassword(e.target.value)} required /><br />

        <button type="submit" className="fom_btn">login</button>
      </form>
    </div>
  )
}

export default Login
